async function request(path, options) {
  const response = await fetch(path, options)
  if (!response.ok) throw new Error(`HTTP ${response.status} for ${path}`)
  return response.json()
}

/** The orders with the given status, or every order when `status` is empty. */
export function listOrders(status = '') {
  const query = status ? `?status=${encodeURIComponent(status)}` : ''
  return request(`/api/orders${query}`)
}

/** Sets an order's status on the server; resolves with the updated order. */
export function updateStatus(id, status) {
  return request(`/api/orders/${encodeURIComponent(id)}/status`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  })
}

import { createServer } from 'node:http'
import { readFile } from 'node:fs/promises'
import { extname, join, normalize, sep } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = fileURLToPath(new URL('.', import.meta.url))
const publicDir = join(root, 'public')
const port = Number(process.env.PORT ?? 4173)

// Every start serves the same orders, so a restart resets the data.
const seed = JSON.parse(
  await readFile(join(root, 'data', 'orders.json'), 'utf8'),
)
const orders = structuredClone(seed)

// Listing every order scans the whole table; a status filter uses an index.
const LIST_ALL_MS = 900
const LIST_FILTERED_MS = 120
const UPDATE_MS = 150
const STATUSES = ['new', 'packed', 'shipped']

const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

function send(response, status, body) {
  response.writeHead(status, {
    'Content-Type': 'application/json',
    'Cache-Control': 'no-store',
  })
  response.end(JSON.stringify(body))
}

async function bodyOf(request) {
  let text = ''
  for await (const chunk of request) text += chunk
  return text ? JSON.parse(text) : {}
}

async function listOrders(url, response) {
  const status = url.searchParams.get('status')
  await sleep(status ? LIST_FILTERED_MS : LIST_ALL_MS)
  send(
    response,
    200,
    status ? orders.filter((order) => order.status === status) : orders,
  )
}

async function updateStatus(id, request, response) {
  const order = orders.find((candidate) => candidate.id === id)
  if (!order) return send(response, 404, { error: 'No such order' })
  const { status } = await bodyOf(request)
  if (!STATUSES.includes(status))
    return send(response, 400, { error: 'Unknown status' })
  await sleep(UPDATE_MS)
  order.status = status
  order.updatedAt = new Date().toISOString()
  send(response, 200, order)
}

async function api(request, response, url) {
  if (request.method === 'GET' && url.pathname === '/api/orders')
    return listOrders(url, response)
  const status = url.pathname.match(/^\/api\/orders\/([\w-]+)\/status$/)
  if (request.method === 'POST' && status)
    return updateStatus(status[1], request, response)
  send(response, 404, { error: 'Not found' })
}

async function file(response, pathname) {
  const path = normalize(
    join(publicDir, pathname === '/' ? 'index.html' : pathname),
  )
  if (!path.startsWith(publicDir + sep)) return send(response, 404, {})
  try {
    const body = await readFile(path)
    response.writeHead(200, {
      'Content-Type': TYPES[extname(path)] ?? 'application/octet-stream',
      'Cache-Control': 'no-store',
    })
    response.end(body)
  } catch {
    send(response, 404, { error: 'Not found' })
  }
}

const server = createServer((request, response) => {
  const url = new URL(request.url, 'http://localhost')
  const work = url.pathname.startsWith('/api/')
    ? api(request, response, url)
    : file(response, url.pathname)
  work.catch((error) => send(response, 500, { error: error.message }))
})

server.listen(port, '127.0.0.1', () =>
  console.log(`Dispatch console on http://127.0.0.1:${port}`),
)

import { money, statusLabel, updatedAt } from './format.js'

function cell(className, text) {
  const span = document.createElement('span')
  span.className = className
  span.textContent = text
  return span
}

function row(order, onShip) {
  const item = document.createElement('li')
  item.dataset.order = order.id
  item.append(
    cell('id', order.id),
    cell('customer', order.customer),
    cell('state', statusLabel(order.status)),
    cell('total', money(order.total)),
    cell('updated', updatedAt(order.updatedAt)),
  )
  if (order.status === 'packed') {
    const button = document.createElement('button')
    button.type = 'button'
    button.className = 'ship'
    button.textContent = 'Mark shipped'
    button.addEventListener('click', () => onShip(order.id))
    item.append(button)
  }
  return item
}

/** Draws the orders screen for `state` into the elements of `screen`. */
export function render(screen, state, { onShip }) {
  screen.status.textContent = state.loading
    ? state.loaded
      ? 'Refreshing…'
      : 'Loading orders…'
    : ''
  screen.error.textContent = state.error ?? ''
  screen.error.hidden = !state.error
  screen.empty.hidden =
    state.loading || !state.loaded || state.orders.length > 0
  screen.list.replaceChildren(
    ...state.orders.map((order) => row(order, onShip)),
  )
  for (const button of screen.filters)
    button.setAttribute(
      'aria-pressed',
      String(button.dataset.filter === state.filter),
    )
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createStore } from '../public/src/store.js'
import { money, statusLabel } from '../public/src/format.js'

const ORDERS = [
  { id: 'ORD-1', customer: 'A', status: 'new', total: 10, updatedAt: '' },
  { id: 'ORD-2', customer: 'B', status: 'packed', total: 20, updatedAt: '' },
]

test('loading asks for the selected filter and shows its orders', async () => {
  const asked = []
  const store = createStore({
    listOrders: async (status) => {
      asked.push(status)
      return ORDERS.filter((order) => !status || order.status === status)
    },
  })
  await store.load('packed')
  assert.deepEqual(asked, ['packed'])
  assert.equal(store.state.filter, 'packed')
  assert.deepEqual(
    store.state.orders.map((order) => order.id),
    ['ORD-2'],
  )
  assert.equal(store.state.loading, false)
})

test('a failed first load says the orders could not be loaded', async () => {
  const store = createStore({
    listOrders: async () => {
      throw new Error('HTTP 503')
    },
  })
  await store.load('')
  assert.equal(store.state.error, 'Could not load orders.')
  assert.equal(store.state.loading, false)
})

test('subscribers hear about each change', async () => {
  const store = createStore({ listOrders: async () => ORDERS })
  const seen = []
  store.subscribe((state) => seen.push(state.loading))
  await store.load('')
  assert.deepEqual(seen, [false])
})

test('statuses and totals are shown the way the team reads them', () => {
  assert.equal(statusLabel('packed'), 'Packed')
  assert.equal(money(89.5), '€89.50')
})
